import sys, importlib.util, jax, jax.numpy as jnp, numpy as np
def load(p):
    s=importlib.util.spec_from_file_location("m"+str(abs(hash(p))),p); m=importlib.util.module_from_spec(s); s.loader.exec_module(m); return m
new=load('"'"'/workspace/losses.py'"'"'); old=load('"'"'/tmp/losses_orig.py'"'"')
B,T,D,V,K=4,16,8,50,20
k=jax.random.key(0); ks=jax.random.split(k,6)
hidden=jax.random.normal(ks[0],(B,T,D)); W=jax.random.normal(ks[1],(D,V))
tokens=jax.random.randint(ks[2],(B,T),0,V); mask=jnp.ones((B,T),bool).at[:,:3].set(False)
adv=jnp.array([1.,-1.,.5,-.5])
def mk(Wq):
    lq=jax.nn.log_softmax(hidden@Wq); tgt=jnp.roll(tokens,-1,1)
    tl=jnp.take_along_axis(lq,tgt[...,None],-1)[...,0]; tlp,tid=jax.lax.top_k(lq,K)
    return dict(tokens=tokens,mask=mask,advantages=adv,sampling_token_logprobs=tl,sampler_topk_ids=tid,sampler_topk_logprobs=tlp)
for Wq in [W, W+0.3*jax.random.normal(ks[3],W.shape)]:
    b=mk(Wq)
    for c in [None, new.ISCorrection(high=2.0,outside="clamp"), new.ISCorrection(level="seq_mean",low=0.9,high=1.1,sign="ppo")]:
        gn=jax.grad(lambda W: new.loss_fn_rl(hidden,lambda x:x@W,b,c,chunk=8)[0])(W)
        go=jax.grad(lambda W: old.loss_fn_rl(hidden,lambda x:x@W,b,c,chunk=8)[0])(W)
        bb={k:v for k,v in b.items() if '"'"'topk'"'"' not in k}
        g1=jax.grad(lambda W: new.loss_fn_rl(hidden,lambda x:x@W,bb,c,chunk=8)[0])(W)
        print(float(jnp.abs(gn-go).max()), float(jnp.abs(go).max()), float(jnp.abs(g1-go).max()))
# zero-mean check: single context, exact expectation over y~q of grad wrt logits
z=jax.random.normal(ks[4],(V,)); zq=z+0.5*jax.random.normal(ks[5],(V,))
lq=jax.nn.log_softmax(zq); tlp,tid=jax.lax.top_k(lq,K)
for c in [None,new.ISCorrection(high=2.0,outside="clamp"),new.ISCorrection(low=0.8,high=1.2,sign="ppo")]:
  def g(y):
    def f(z):
        lpv=jax.nn.log_softmax(z)[None,None]; lp=lpv[...,y]
        w=new.is_weight(lp-lq[y],jnp.array([[False]]),c)
        base=new.score_baseline(lpv,lp,lq[y][None,None],jnp.array([[y]]),tlp[None,None],tid[None,None],jnp.array([[False]]),c)
        return (w*lp-base).sum()
    return jax.grad(f)(z)
  G=sum(jnp.exp(lq[y])*g(y) for y in range(V))
  def g0(y):
    return jax.grad(lambda z: (new.is_weight(jax.nn.log_softmax(z)[y]-lq[y],jnp.array([[False]]),c)*jax.nn.log_softmax(z)[y]).sum())(z)
  G0=sum(jnp.exp(lq[y])*g0(y) for y in range(V))
  print("E_q grad new", float(jnp.abs(G).max()), "old", float(jnp.abs(G0).max()))
